scripts.事件101_2.txt:
	If ($Event == 1002) @Label1;
	
	Goto @end;
	
@Label1:
	If ($Result <> 3) @end;
	
	FadeOut();
	SetPlayerPos(36, 36);
	SetPlayerDir(4);
	AddNpc("月眉儿.ini", 34, 10, 0);
	AddNpc("纳兰真.ini", 35, 8, 0);
	SetPlayerScn();
	FadeIn();
	PlayerRunTo(34, 15);
	SetPlayerDir(4);
	
	Say("杨影枫：啊，真儿，月眉儿……", 4);
	Say("纳兰真：影枫哥……", 10);
	
	NpcGoto("纳兰真", 34, 13);
	SetNpcDir("纳兰真", 0);
	
	Say("杨影枫：真儿，我可找到你了，你怎么样？", 2);
	Say("纳兰真：影枫哥，我没什么事，这位月姑娘并没有伤害我。", 9);
	Say("杨影枫：真儿，没事就好，没事就好。她、她、这位月姑娘，是你的亲妹妹。", 2);
	Say("纳兰真：啊！", 15);
	Say("杨影枫：真儿，你娘在禁地的密室里留有一封书信给你。其实在你很小的时候，你娘就带着你妹妹，就是月眉儿，投奔了飞龙堡。", 2);
	Say("纳兰真：啊！真的吗？", 15);
	Say("杨影枫：当然是真的，前些天月姑娘假扮你到忘忧岛查探，也发现了这个秘密。", 2);
	Say("纳兰真：这么说，", 15);
	SetNpcDir("纳兰真", 3);
	Sleep(1000);
	Say("纳兰真：你、你就是我妹妹了？", 15);
	Say("月眉儿：……是又怎样？", 27);
	Say("纳兰真：原来我还有个妹妹。那……那我娘呢？", 15);
	Say("月眉儿：她早已经去世了。", 27);
	
	SetNpcDir("纳兰真", 0);
	Say("杨影枫：真儿，……有个坏消息要告诉你，你爹，也已经去世了。", 5);
	Say("纳兰真：不、不，怎么会这样，到底怎么回事儿啊！", 14);

	SetNpcDir("纳兰真", 3);
	Say("月眉儿：行了行了，杨影枫，我姐姐我已经还给你了，现在该算算我们俩之间的账了。", 27);
	Say("杨影枫：你又想干什么？", 2);
	Say("月眉儿：杨影枫，虽然上官飞龙不是我的生父，但不管怎么说，他对我有养育之恩；何况，我娘也因你爹的事情而死，这件事情不能就这样算了。我们现在该到了做个了断、结束所有恩怨的时候了！", 27);
	Say("杨影枫：好吧，既然你对以前的事情一直耿耿于怀，那来一场了断也好。你要如何？", 2);
	Say("月眉儿：很简单，你，我，凌绝峰顶，决一死战。", 27);
	Say("纳兰真：不要……", 15);
	Say("杨影枫：好，我接受。", 2);

	Assign($Event, 1005);
	
	FadeOut();
	Say("三天后，凌绝峰顶……");
	LoadMap("map_002_凌绝峰峰顶.map");
	LoadNpc("map002_result3.npc");
	LoadObj("map002_result3.obj");
	ChangeMapColor(255, 255, 255);
	ChangeAsfColor(255, 255, 255);
	SetPlayerPos(11, 18);
	SetPlayerDir(2);
	EnableNpcAI();
	SetMapPos(4, 3);
	FadeIn();
	SetMapTrap(1, "");
	SetMapTrap(2, "");
	SetMapTrap(3, "");
	SetMapTrap(5, "");
	SetMapTrap(7, "");
	
	Say("月眉儿：开始吧。", 27);
	Say("纳兰真：你们可不可以不要打？不要打好不好？", 15);
	Say("杨影枫：真儿，你不懂的，这就是江湖。", 2);
	Say("杨影枫：开始吧。", 2);
	
	SetNpcRelation("月眉儿", 1);
	
	Goto @end;
@end:
	Return;

