scripts.蔷薇对话.txt:
	If ($Event == 2009) @2009;
	Return;
	
@2009:
	StopMusic();
	PlayMusic("mc013.mp3");
	Say("杨影枫：薇儿！",2);
	Say("蔷薇：影枫哥！我终于把你给盼来了，呜……",32);
	Say("杨影枫：薇儿！让你受苦了。",2);
	Say("蔷薇：呜……你不知道你不在的时候，我有多想你，你要是再不来，我就准备跳塔自杀了。",32);
	Say("杨影枫：薇儿！你怎么这么傻……你知道真儿在哪里吗？",8);
	Say("蔷薇：你只知道关心她，我也受了伤呢。",32);
	Say("杨影枫：你伤在哪里，不要紧吧。",2);
	Say("蔷薇：我的伤很严重，我都快要死了。",30);
	Say("杨影枫：你到底伤在哪里，让我来看一看。",2);
	Say("蔷薇：（指着自己的胸口）我的伤在这里，不信，你用手摸一摸。",30);
	Say("杨影枫：……薇儿，别开玩笑了，纳兰真到底在哪里？",3);
	Say("蔷薇：哼，你一点都不关心我。心里只惦记着别人。",31);
	NpcGoto("蔷薇",34,19);
	PlayerGoto(35,18);
	SetPlayerDir(1);
	Say("杨影枫：薇儿，我……其实……我是喜欢你的。",3);
	Watch("杨影枫","蔷薇",0);
	Say("蔷薇：真的吗？那你就吻一下我。",30);
	Say("杨影枫：薇儿，我……",3);

	Choose("是否亲吻蔷薇？","A、是","B、否",$wangwei);
	If ($wangwei == 0) @kiss; // yes
	Say("杨影枫：薇儿……你别这样好吗？快告诉我纳兰真到底怎么样了。",3);
	Goto @nokiss;
	
@kiss:
	FadeOut();
	Say("杨影枫轻吻了蔷薇额头");
	FadeIn();

@nokiss:
	Say("蔷薇：真儿姐没有事情，昨天和她爹一起走了，我也不知道去了哪里。",29);
	Say("杨影枫：唉……我要到哪里去找真儿呢？",5);
	Sleep(1000);	
	Say("蔷薇：我爹怎么没有跟你一起来呢？",32);
	Say("杨影枫：薇儿！说了你不要太难过，你爹被纳兰潜凛打成重伤，恐怕……",5);
	Say("蔷薇：爹……不行，我要回去看爹爹。",32);
	Say("杨影枫：好吧，我们现在就回落叶谷去。",2);
	SetNpcKind("蔷薇",3);
	SetNpcDeathScript("蔷薇","主角死亡.txt");
	Assign($Event, 2010);
	StopMusic();
	PlayMusic("mc024.mp3");
	Memo("送蔷薇回落叶谷");
	Return;

